package com.isoform

import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.uimanager.annotations.ReactProp
import com.facebook.react.viewmanagers.IsoAudioViewManagerDelegate
import com.facebook.react.viewmanagers.IsoAudioViewManagerInterface

/**
 * Bridge between Fabric and `IsoAudioView`: props, commands and events.
 * `IsoAudioViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/media/audio/native/IsoAudioViewNativeComponent.ts`.
 */
@ReactModule(name = IsoAudioViewManager.NAME)
class IsoAudioViewManager :
  SimpleViewManager<IsoAudioView>(),
  IsoAudioViewManagerInterface<IsoAudioView> {

  private val delegate = IsoAudioViewManagerDelegate(this)

  override fun getDelegate(): ViewManagerDelegate<IsoAudioView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): IsoAudioView = IsoAudioView(context)

  override fun onDropViewInstance(view: IsoAudioView) {
    view.release()
    super.onDropViewInstance(view)
  }

  // ── props ──

  @ReactProp(name = "src")
  override fun setSrc(view: IsoAudioView, value: String?) = view.setSource(value)

  @ReactProp(name = "controls", defaultBoolean = true)
  override fun setControls(view: IsoAudioView, value: Boolean) = view.setControls(value)

  @ReactProp(name = "autoPlay")
  override fun setAutoPlay(view: IsoAudioView, value: Boolean) = view.setAutoPlay(value)

  @ReactProp(name = "loop")
  override fun setLoop(view: IsoAudioView, value: Boolean) = view.setLoop(value)

  @ReactProp(name = "muted")
  override fun setMuted(view: IsoAudioView, value: Boolean) = view.setMuted(value)

  @ReactProp(name = "rate", defaultFloat = 1f)
  override fun setRate(view: IsoAudioView, value: Float) = view.setRate(value)

  @ReactProp(name = "volume", defaultFloat = 1f)
  override fun setVolume(view: IsoAudioView, value: Float) = view.setVolume(value)

  @ReactProp(name = "title")
  override fun setTitle(view: IsoAudioView, value: String?) = view.setTitle(value)

  @ReactProp(name = "artist")
  override fun setArtist(view: IsoAudioView, value: String?) = view.setArtist(value)

  @ReactProp(name = "playlistIndex", defaultInt = -1)
  override fun setPlaylistIndex(view: IsoAudioView, value: Int) = view.setPlaylist(value, view.playlistCount)

  @ReactProp(name = "playlistCount")
  override fun setPlaylistCount(view: IsoAudioView, value: Int) = view.setPlaylist(view.playlistIndex, value)

  @ReactProp(name = "artwork")
  override fun setArtwork(view: IsoAudioView, value: String?) = view.setArtwork(value)

  // ── commands ──

  override fun play(view: IsoAudioView) = view.play()

  override fun pause(view: IsoAudioView) = view.pause()

  override fun seekTo(view: IsoAudioView, seconds: Double) = view.seekTo(seconds)

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    IsoAudioView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "IsoAudioView"
  }
}
